python3 -c "
import json
from collections import Counter

# Joint distribution: ambiguity_type × condition × violation_level × model
dist = Counter()
for f in ['full_study/episodes/gpt-4.1/episodes.jsonl','full_study/episodes/gpt-5.4/episodes.jsonl']:
    for line in open(f):
        d = json.loads(line)
        dist[(d['ambiguity_type'], d['condition'], d['model'])] += 1

for key in sorted(dist.keys()):
    print(f'{key}: {dist[key]}')

print()
# Now violation_level distribution per ambiguity_type
vl_dist = Counter()
for f in ['full_study/judgments/gpt-4.1/judgments.jsonl','full_study/judgments/gpt-5.4/judgments.jsonl']:
    for line in open(f):
        d = json.loads(line)
        vl_dist[(d['ambiguity_type'], d['judgment']['violation_level'])] += 1

print('Violation levels per ambiguity_type:')
for at in sorted(set(k[0] for k in vl_dist)):
    parts = {vl: vl_dist.get((at, vl), 0) for vl in ['none','minor','moderate','critical']}
    print(f'  {at}: {parts}')
"

